    hb.appendChild(document.createTextNode("ループ停止中（上限に達したか、同じカードでスタック） — ここの「再開」、kanban ツールの resume、または /kanban loop on で解除する（スイッチを ON にしても再開しない） "));
    hb.appendChild(resumeBtn(ctx));
